<script setup>
import { useForm } from '@inertiajs/vue3'
import { Head } from '@inertiajs/vue3'
import AdminLayout from '../../../Layouts/AdminLayout.vue'
import PageHeader from '../../../Components/Ui/PageHeader.vue'
import AccountingNav from '../../../Components/Accounting/AccountingNav.vue'
import AccountingPanel from '../../../Components/Accounting/AccountingPanel.vue'
import { useConfirm } from '../../../Composables/useConfirm'
import { localDateInput } from '../../../Utils/dateInput'
defineOptions({layout:AdminLayout})
const props=defineProps({asset:Object,disposalPaymentMethods:Array,nextDepreciationAmount:Number,canUpdate:Boolean,currency:Object,urls:Object});const {ask}=useConfirm();const today=localDateInput();const depreciation=useForm({period_month:today.slice(0,7),posted_on:today,notes:''});const disposal=useForm({disposed_on:today,disposal_proceeds:0,disposal_payment_method:props.disposalPaymentMethods.find(m=>m.code==='bank_transfer')?.code||props.disposalPaymentMethods[0]?.code||'',notes:''});const money=v=>`${new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))} ${props.currency.symbol}`;const postDep=()=>depreciation.post(props.urls.depreciation,{preserveScroll:true});async function dispose(){const yes=await ask({title:'استبعاد الأصل؟',message:'سيُوقف الإهلاك ويُرحّل قيد إخراج التكلفة ومجمع الإهلاك وربح أو خسارة البيع. لا يمكن التراجع إلا بقيد تصحيح.',confirmLabel:'استبعاد وترحيل',danger:true});if(yes)disposal.post(props.urls.dispose,{preserveScroll:true})}
</script>
<template><Head :title="`${asset.number} — ${asset.name}`"/><PageHeader :title="asset.name" icon="bi-building-gear" :subtitle="`${asset.number} · ${asset.statusLabel}`"><template #actions><a :href="urls.index" class="btn btn-light"><i class="bi bi-arrow-right"></i> كل الأصول</a></template></PageHeader><AccountingNav :urls="urls" active="fixedAssets"/><div class="metrics"><article><small>تكلفة الأصل</small><strong>{{money(asset.cost)}}</strong></article><article><small>مجمع الإهلاك</small><strong>{{money(asset.accumulated)}}</strong></article><article class="book"><small>القيمة الدفترية</small><strong>{{money(asset.bookValue)}}</strong></article><article><small>الإهلاك الشهري</small><strong>{{money(asset.monthlyDepreciation)}}</strong></article></div><div class="asset-layout"><main><AccountingPanel title="بيانات الأصل" :description="asset.description||'البيانات الأساسية والمرجع المحاسبي للأصل.'" icon="bi-card-list"><dl><div><dt>الحالة</dt><dd><em :data-status="asset.status">{{asset.statusLabel}}</em></dd></div><div><dt>الفئة</dt><dd>{{asset.category||'—'}}</dd></div><div><dt>تاريخ الشراء</dt><dd>{{asset.acquisitionDate}}</dd></div><div><dt>بدء الاستخدام</dt><dd>{{asset.inServiceDate}}</dd></div><div><dt>العمر الإنتاجي</dt><dd>{{asset.usefulLifeMonths}} شهر</dd></div><div><dt>المورد</dt><dd>{{asset.vendor||'—'}}</dd></div><div><dt>عملة الشراء</dt><dd>{{asset.currencyCode}} × {{asset.exchangeRate}}</dd></div><div><dt>التكلفة الأصلية</dt><dd>{{asset.foreignCost.toFixed(2)}} {{asset.currencyCode}}</dd></div><div><dt>قيد الشراء</dt><dd><a v-if="asset.purchaseEntry" :href="asset.purchaseEntry.url">{{asset.purchaseEntry.number}}</a><span v-else>—</span></dd></div><div><dt>قيد الاستبعاد</dt><dd><a v-if="asset.disposalEntry" :href="asset.disposalEntry.url">{{asset.disposalEntry.number}}</a><span v-else>—</span></dd></div></dl><p v-if="asset.notes" class="notes">{{asset.notes}}</p></AccountingPanel><AccountingPanel title="سجل الإهلاك" :description="`${asset.depreciations.length} قيد إهلاك`" icon="bi-clock-history" compact><div class="depreciations"><a v-for="row in asset.depreciations" :key="row.id" :href="row.entry?.url||'#'"><span><strong>{{row.period}}</strong><small>{{row.postedOn}}</small></span><span><small>إهلاك الشهر</small><bdi>{{money(row.amount)}}</bdi></span><span><small>المجمع بعده</small><bdi>{{money(row.accumulatedAfter)}}</bdi></span><em>{{row.entry?.number||'بلا قيد'}}</em><i class="bi bi-chevron-left"></i></a><div v-if="!asset.depreciations.length" class="empty"><i class="bi bi-clock"></i><strong>لم يُرحّل إهلاك بعد</strong></div></div></AccountingPanel></main><aside v-if="canUpdate"><AccountingPanel title="إهلاك شهري" :description="`المتوقع الآن ${money(nextDepreciationAmount)}`" icon="bi-graph-down-arrow"><form class="action-form" @submit.prevent="postDep"><label><span>شهر الإهلاك</span><input v-model="depreciation.period_month" type="month" class="form-control" required :disabled="asset.status==='disposed'"></label><label><span>تاريخ القيد</span><input v-model="depreciation.posted_on" type="date" class="form-control" required :disabled="asset.status==='disposed'"></label><label><span>ملاحظات</span><textarea v-model="depreciation.notes" rows="2" class="form-control" :disabled="asset.status==='disposed'"></textarea></label><button class="btn btn-primary" :disabled="asset.status==='disposed'||asset.remainingDepreciable<=.01"><i class="bi bi-journal-check"></i> ترحيل الإهلاك</button></form></AccountingPanel><AccountingPanel title="استبعاد أو بيع" description="يسجل خروج الأصل وربح أو خسارة البيع تلقائياً." icon="bi-box-arrow-down" tone="amber"><section v-if="asset.status==='disposed'" class="disposed"><i class="bi bi-check-circle-fill"></i><div><strong>الأصل مستبعد</strong><small>{{asset.disposedOn}} · متحصلات {{money(asset.disposalProceeds)}}</small></div></section><form v-else class="action-form" @submit.prevent="dispose"><label><span>تاريخ الاستبعاد</span><input v-model="disposal.disposed_on" type="date" class="form-control" required></label><label><span>متحصلات البيع</span><input v-model="disposal.disposal_proceeds" type="number" min="0" step=".01" class="form-control" required></label><label><span>طريقة التحصيل</span><select v-model="disposal.disposal_payment_method" class="form-select"><option v-for="method in disposalPaymentMethods" :key="method.code" :value="method.code">{{method.label}}</option></select></label><label><span>ملاحظات</span><textarea v-model="disposal.notes" rows="2" class="form-control"></textarea></label><button class="btn btn-danger"><i class="bi bi-box-arrow-down"></i> استبعاد وترحيل القيد</button></form></AccountingPanel></aside></div></template>
<style scoped>.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:10px}.metrics article{display:grid;padding:12px 14px;border:1px solid #dfe7e2;border-radius:13px;background:#fff}.metrics small{color:#7d8a82;font-size:.59rem}.metrics strong{font-size:.82rem}.metrics .book{color:#1f6b50;border-color:#acd2b7;background:#f1f8f3}.asset-layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(280px,.65fr);align-items:start;gap:11px}.asset-layout main,.asset-layout aside{display:grid;gap:10px}.asset-layout aside{position:sticky;top:183px}dl{display:grid;grid-template-columns:1fr 1fr;margin:0;gap:0 14px}dl>div{display:flex;justify-content:space-between;gap:8px;padding:8px 0;border-bottom:1px solid #edf1ee}dt{color:#7d8a82;font-size:.61rem}dd{margin:0;font-size:.64rem;font-weight:800}dd em{padding:3px 7px;border-radius:999px;color:#1f6b50;background:#e6f3ea;font-size:.55rem;font-style:normal}dd em[data-status=disposed]{color:#66746b;background:#eef2ef}.notes{margin:11px 0 0;padding:9px;border-radius:9px;color:#65736a;background:#f5f8f6;font-size:.62rem;line-height:1.6}.depreciations{display:grid}.depreciations>a{display:grid;grid-template-columns:1fr 1fr 1fr 100px 18px;align-items:center;gap:8px;padding:10px 13px;border-bottom:1px solid #edf1ee;color:#35463b}.depreciations a>span{display:grid}.depreciations strong,.depreciations bdi{font-size:.65rem}.depreciations small{color:#829087;font-size:.55rem}.depreciations em{font-size:.58rem;font-style:normal}.depreciations>a>i{font-size:.52rem}.action-form{display:grid;gap:8px}.action-form label{display:grid;gap:4px}.action-form label>span{font-size:.61rem;font-weight:850}.disposed{display:flex;gap:8px;padding:10px;border-radius:10px;color:#1f6b50;background:#eaf5ed}.disposed div{display:grid}.disposed strong{font-size:.68rem}.disposed small{font-size:.58rem}.empty{display:grid;justify-items:center;gap:4px;padding:45px;color:#839087}.empty strong{font-size:.7rem}@media(max-width:950px){.asset-layout{grid-template-columns:1fr}.asset-layout aside{position:static;grid-template-columns:1fr 1fr}}@media(max-width:650px){.metrics{grid-template-columns:1fr 1fr}.asset-layout aside{grid-template-columns:1fr}dl{grid-template-columns:1fr}.depreciations>a{grid-template-columns:1fr 1fr auto}.depreciations>a>span:nth-child(3){display:none}.depreciations a>i{display:none}}</style>
